#!/bin/sh
# hy — CodeBuddy 版工作流插件 一键安装器（自包含，全局安装）
# 用法: curl -fsSL http://10.1.34.16:30021/AI%E8%B5%8B%E8%83%BD/hy%E6%8F%92%E4%BB%B6-codebuddy/install.sh | sh
# 安装目标: ~/.codebuddy/hy-plugin（插件本体）+ ~/.codebuddy/skills/（全局技能）
set -eu
if (set -o pipefail 2>/dev/null); then set -o pipefail; fi
echo "[i] hy 插件安装器（CodeBuddy 版）v1.0"
echo ""

CB_PLUGIN_DIR="$HOME/.codebuddy/hy-plugin"
CB_SKILLS_DIR="$HOME/.codebuddy/skills"
TMP_DIR=$(mktemp -d)
mkdir -p "$CB_PLUGIN_DIR" "$CB_SKILLS_DIR"
echo "[i] 解压插件到临时目录 ..."

B64=''
echo "$B64" | base64 -d 2>/dev/null | tar -xzf - -C "$TMP_DIR" 2>/dev/null || {
  python3 -c "
import base64, tarfile, os, sys
b64 = ''''''
data = base64.b64decode(b64)
tmp = os.path.join(os.environ.get('TMPDIR','/tmp'),'hy-codebuddy-plugin.tar.gz')
with open(tmp,'wb') as f: f.write(data)
tarfile.open(tmp).extractall(path=sys.argv[1])
os.remove(tmp)
" "$TMP_DIR"
}

echo "[i] 部署全局技能到 $CB_SKILLS_DIR ..."
cp -rf "$TMP_DIR/skills/." "$CB_SKILLS_DIR/"
echo "[i] 部署插件本体到 $CB_PLUGIN_DIR ..."
cp -rf "$TMP_DIR/." "$CB_PLUGIN_DIR/"
rm -rf "$TMP_DIR"

echo ""
echo "[OK] hy 插件（CodeBuddy 版）安装完成！"
echo ""
echo "[i] 使用方式（命令格式与 Claude Code 兼容）："
echo "    /hy:run <需求> · /hy:run-crud <需求> · @hy:frontend <操作> 等"
echo ""
echo "[i] 门禁（可选）：把 $CB_PLUGIN_DIR/hooks.settings.json 的 hooks 字段"
echo "    合并到 ~/.codebuddy/settings.json（PreToolUse 生效；PostToolUse 仅提示）"
echo "[i] 项目级技能须放工作区根目录 .codebuddy/skills/（嵌套目录不识别）"
echo "[i] 如果 CodeBuddy 已打开，重启生效。"
